    // DETEKCJA ŁUPU
    // =========================================================

    function isTargetLootWindow(windowElement) {
        if (!windowElement) {
            return false;
        }

        const hasAnyItem = !!windowElement.querySelector(
            '.loot-window .items-wrapper .item, .item'
        );

        const hasLegendaryItem = !!windowElement.querySelector(
            '[data-frame-mania-rarity="legendary"], [data-item-type="t-leg"]'
        );

        /*
         * ZWYKŁY TEST:
         * uruchamia efekt na zwykłym loocie, ale nie na legendzie.
         *
         * LEGENDARY:
         * docelowy tryb dodatku — efekt wyłącznie dla legend.
         */
        if (settings.dropMode === DROP_MODE_LEGENDARY) {
            return hasLegendaryItem;
        }

        return hasAnyItem && !hasLegendaryItem;
    }

    function updateLootWindows() {
        document.querySelectorAll('.loot-wnd').forEach(windowElement => {
            applyGlowToWindow(windowElement);
        });

        syncMapGlowOverlay();
    }

