    function buildChatEmoticonCatalogHtml() {
        return Object.entries(CHAT_EMOTICONS)
            .map(([name, config]) => {
                const token =
                    `:${name}:`;

                return `
                    <button
                        class="shacal-emote-catalog-item"
                        type="button"
                        data-shacal-emote-token="${escapeHtml(token)}"
                        title="Kliknij, aby skopiować ${escapeHtml(token)}"
                    >
                        <span class="shacal-emote-catalog-image-wrap">
                            <img
                                class="shacal-emote-catalog-image"
                                src="${escapeHtml(config.src)}"
                                alt="${escapeHtml(token)}"
                                loading="lazy"
                            >
                        </span>
                        <span class="shacal-emote-catalog-code">${escapeHtml(token)}</span>
                    </button>
                `;
            })
            .join('');
    }

    const CHAT_EMOTICON_TOKEN_RE =
        /:([a-z0-9_+-]{2,32}):/gi;

    function isChatEmoticonContext(node) {
        const element =
            node instanceof Element
                ? node
                : node?.parentElement;

        if (!element || !element.isConnected) return false;

        if (
            element.closest(
                '#shacal-glow-panel, script, style, textarea, input, select, option, [contenteditable="true"]'
            )
        ) {
            return false;
        }

        return !!element.closest(
            '[class*="chat"], [class*="Chat"], [id*="chat"], [id*="Chat"]'
        );
    }

    function createChatEmoticonElement(name, token) {
        const config =
            CHAT_EMOTICONS[String(name || '').toLowerCase()];

        if (!config) return null;

        const image =
            document.createElement('img');

        image.className =
            'shacal-chat-emote';

        image.src =
            config.src;

        image.alt =
            config.alt || token;

        image.title =
            config.title || name;

        image.dataset.shacalEmoteToken =
            token;

        image.dataset.shacalEmoteName =
            String(name || '').toLowerCase();

        image.setAttribute(
            'aria-label',
            token
        );

        return image;
    }

    function renderChatEmoticonsInTextNode(textNode) {
        if (
            !settings.chatEmoticonsEnabled ||
            !textNode ||
            textNode.nodeType !== Node.TEXT_NODE ||
            !textNode.parentElement ||
            !isChatEmoticonContext(textNode)
        ) {
            return;
        }

        const source =
            String(textNode.nodeValue || '');

        if (!source.includes(':')) {
            return;
        }

        CHAT_EMOTICON_TOKEN_RE.lastIndex = 0;

        let match;
        let lastIndex = 0;
        let changed = false;

        const fragment =
            document.createDocumentFragment();

        while (
            (match = CHAT_EMOTICON_TOKEN_RE.exec(source))
        ) {
            const token =
                match[0];

            const name =
                match[1].toLowerCase();

            const config =
                CHAT_EMOTICONS[name];

            if (!config) {
                continue;
            }

            if (match.index > lastIndex) {
                fragment.appendChild(
                    document.createTextNode(
                        source.slice(lastIndex, match.index)
                    )
                );
            }

            const image =
                createChatEmoticonElement(
                    name,
                    token
                );

            if (image) {
                fragment.appendChild(image);
                changed = true;
            } else {
                fragment.appendChild(
                    document.createTextNode(token)
                );
            }

            lastIndex =
                match.index + token.length;
        }

        if (!changed) {
            return;
        }

        if (lastIndex < source.length) {
            fragment.appendChild(
                document.createTextNode(
                    source.slice(lastIndex)
                )
            );
        }

        textNode.replaceWith(fragment);
    }

    function renderChatEmoticonsInRoot(root) {
        if (
            !settings.chatEmoticonsEnabled ||
            !root
        ) {
            return;
        }

        if (root.nodeType === Node.TEXT_NODE) {
            renderChatEmoticonsInTextNode(root);
            return;
        }

        if (!(root instanceof Element) && root !== document.body) {
            return;
        }

        if (
            root instanceof Element &&
            root.matches(
                '#shacal-glow-panel, script, style, textarea, input, select, option, [contenteditable="true"], .shacal-chat-emote'
            )
        ) {
            return;
        }

        const walker =
            document.createTreeWalker(
                root,
                NodeFilter.SHOW_TEXT,
                {
                    acceptNode(node) {
                        const value =
                            String(node.nodeValue || '');

                        if (
                            !value.includes(':') ||
                            !isChatEmoticonContext(node)
                        ) {
                            return NodeFilter.FILTER_REJECT;
                        }

                        return NodeFilter.FILTER_ACCEPT;
                    }
                }
            );

        const nodes = [];
        let current;

        while ((current = walker.nextNode())) {
            nodes.push(current);
        }

        nodes.forEach(
            renderChatEmoticonsInTextNode
        );
    }

    function restoreChatEmoticonTokens() {
        document
            .querySelectorAll(
                '.shacal-chat-emote[data-shacal-emote-token]'
            )
            .forEach(image => {
                image.replaceWith(
                    document.createTextNode(
                        image.dataset.shacalEmoteToken ||
                        image.alt ||
                        ''
                    )
                );
            });
    }

    function refreshChatEmoticons() {
        if (!settings.chatEmoticonsEnabled) {
            restoreChatEmoticonTokens();
            return;
        }

        const roots =
            document.querySelectorAll(
                '[class*="chat"], [class*="Chat"], [id*="chat"], [id*="Chat"]'
            );

        roots.forEach(root => {
            if (!root.closest('#shacal-glow-panel')) {
                renderChatEmoticonsInRoot(root);
            }
        });
    }

    // =========================================================
    // CZAT — AUTOMATYCZNE OGŁASZANIE ZDOBYTYCH LEGEND
    // =========================================================

    const CHAT_ANNOUNCEMENT_SESSION_KEY =
        'shacalLegendaryGlowAnnouncedLegendIds';

    let legendaryChatTrackerArmed = false;
    let legendaryChatProcessedLootNodes = new WeakSet();
    let legendaryChatRetryingLootNodes = new WeakSet();
    const legendaryChatCandidates = new Map();
    const legendaryChatQueuedIds = new Set();
    const legendaryChatQueue = [];
    let legendaryChatQueueBusy = false;

    const legendaryChatAnnouncedIds = (() => {
        try {
            const parsed = JSON.parse(
                sessionStorage.getItem(CHAT_ANNOUNCEMENT_SESSION_KEY) || '[]'
            );
            return new Set(Array.isArray(parsed) ? parsed.map(String) : []);
        } catch {
            return new Set();
        }
    })();

    function persistLegendaryChatAnnouncedIds() {
        try {
            sessionStorage.setItem(
                CHAT_ANNOUNCEMENT_SESSION_KEY,
                JSON.stringify(Array.from(legendaryChatAnnouncedIds).slice(-300))
            );
        } catch {}
    }

    function getItemObjectFromElement(element) {
        if (!element || !window.jQuery) return null;

        try {
            return jQuery.data(element)?.item || null;
        } catch {
            return null;
        }
    }

    function getItemIdFromElement(element, itemObject = null) {
        if (itemObject?.id !== undefined && itemObject?.id !== null) {
            return String(itemObject.id);
        }

        const className = String(element?.className || '');
        const match = className.match(/(?:^|\s)item-id-(\d+)(?:\s|$)/);
        return match ? match[1] : null;
    }

    function buildLegendaryChatMessage(itemObject) {
        const itemToken = `ITEM#${itemObject.hid}`;
        let template = String(
            settings.chatMessageTemplate || defaultSettings.chatMessageTemplate
        )
            .replace(/\u00a0/g, ' ')
            .replace(/[\r\n\t]+/g, ' ')
            .replace(/\s{2,}/g, ' ')
            .trim();

        if (!template) {
            return itemToken;
        }

        if (/\{ITEM\}/.test(template)) {
            return template.replace(/\{ITEM\}/g, itemToken).trim();
        }

        return `${template} ${itemToken}`.trim();
    }

    function sendLegendaryGlobalAnnouncement(itemObject) {
        const chat =
            window.Engine?.chatController?.getChatInputWrapper?.();

        if (!chat || !itemObject?.hid) {
            return false;
        }

        const previousChannel = chat.getChannelName?.();
        const previousReceiver = chat.getPrivateReceiver?.();
        const previousStyle = chat.getStyleMessage?.();
        const message = buildLegendaryChatMessage(itemObject);

        try {
            chat.setChannel({ name: 'GLOBAL' });

            if (chat.getChannelName?.() !== 'GLOBAL') {
                throw new Error('Nie udało się przełączyć kanału czatu na GLOBAL.');
            }

            chat.getDataAndSendRequest(message);

            console.log(
                '[Shacal Customizer] Ogłoszono legendę:',
                itemObject.getName?.() || itemObject.name || itemObject.id,
                message
            );

            return true;
        } catch (error) {
            console.warn(
                '[Shacal Customizer] Nie udało się wysłać ogłoszenia legendy:',
                error
            );
            return false;
        } finally {
            try {
                if (previousChannel && previousChannel !== 'GLOBAL') {
                    chat.setChannel(
                        { name: previousChannel },
                        previousReceiver,
                        previousStyle
                    );
                }
            } catch {}
        }
    }

    function findLegendaryInventoryItemForChatTest() {
        const elements = document.querySelectorAll(
            '.inventory-item[data-item-type="t-leg"], ' +
            '.inventory-item[data-frame-mania-rarity="legendary"]'
        );

        for (const element of elements) {
            if (element.closest('.shacal-test-loot-window')) continue;

            const itemObject = getItemObjectFromElement(element);
            if (itemObject?.hid) {
                return itemObject;
            }
        }

        return null;
    }

    function testLegendaryChatAnnouncement() {
        const itemObject = findLegendaryInventoryItemForChatTest();

        if (!itemObject) {
            return {
                ok: false,
                message: 'Brak prawdziwej legendy w ekwipunku do testu.'
            };
        }

        const ok = sendLegendaryGlobalAnnouncement(itemObject);

        return {
            ok,
            message: ok
                ? `Test wysłany na kanał globalny: ${itemObject.getName?.() || itemObject.name || itemObject.id}`
                : 'Nie udało się wysłać wiadomości testowej.'
        };
    }

    function processLegendaryChatQueue() {
        if (legendaryChatQueueBusy) return;

        const entry = legendaryChatQueue.shift();
        if (!entry) return;

        legendaryChatQueueBusy = true;

        const success = sendLegendaryGlobalAnnouncement(entry.itemObject);

        if (success) {
            legendaryChatAnnouncedIds.add(entry.id);
            persistLegendaryChatAnnouncedIds();
            legendaryChatCandidates.delete(entry.id);
        }

        legendaryChatQueuedIds.delete(entry.id);

        setTimeout(() => {
            legendaryChatQueueBusy = false;
            processLegendaryChatQueue();
        }, 1700);
    }

    function enqueueLegendaryGlobalAnnouncement(id, itemObject) {
        if (
            !id ||
            !itemObject?.hid ||
            legendaryChatAnnouncedIds.has(id) ||
            legendaryChatQueuedIds.has(id)
        ) {
            return;
        }

        legendaryChatQueuedIds.add(id);
        legendaryChatQueue.push({ id, itemObject });
        processLegendaryChatQueue();
    }

    function tryAnnounceLegendaryLootElement(element, attempt = 0) {
        if (
            !settings.chatAnnouncementsEnabled ||
            !legendaryChatTrackerArmed ||
            !(element instanceof Element) ||
            !element.isConnected ||
            element.closest('.shacal-test-loot-window')
        ) {
            legendaryChatRetryingLootNodes.delete(element);
            return;
        }

        const itemObject = getItemObjectFromElement(element);
        const id = getItemIdFromElement(element, itemObject);

        if (id && legendaryChatAnnouncedIds.has(id)) {
            legendaryChatProcessedLootNodes.add(element);
            legendaryChatRetryingLootNodes.delete(element);
            return;
        }

        /*
         * Docelowe zachowanie:
         * legenda jest ogłaszana NATYCHMIAST z okna Łupy.
         * Nie czekamy już, aż przedmiot trafi do ekwipunku.
         */
        if (id && itemObject?.hid) {
            legendaryChatCandidates.set(id, {
                hid: itemObject.hid,
                createdAt: Date.now()
            });

            legendaryChatProcessedLootNodes.add(element);
            legendaryChatRetryingLootNodes.delete(element);
            enqueueLegendaryGlobalAnnouncement(id, itemObject);
            return;
        }

        /*
         * DOM okna łupu potrafi pojawić się ułamek sekundy wcześniej niż
         * obiekt Item w jQuery.data(). Krótki retry pozwala złapać HID bez
         * kosztownego skanowania całego DOM-u w każdej klatce.
         */
        if (attempt < 20) {
            legendaryChatRetryingLootNodes.add(element);

            setTimeout(() => {
                tryAnnounceLegendaryLootElement(element, attempt + 1);
            }, 100);

            return;
        }

        legendaryChatRetryingLootNodes.delete(element);

        /*
         * Fallback: jeśli mamy ID, zostawiamy kandydata. Gdy wyjątkowo
         * obiekt Item nie był dostępny w oknie łupu, stary mechanizm
         * ekwipunkowy może nadal dokończyć wysłanie.
         */
        if (id) {
            legendaryChatCandidates.set(id, {
                hid: itemObject?.hid || null,
                createdAt: Date.now()
            });
        }
    }

    function scanLegendaryLootCandidates() {
        if (
            !settings.chatAnnouncementsEnabled ||
            !legendaryChatTrackerArmed
        ) {
            return;
        }

        document.querySelectorAll(
            '.loot-wnd:not(.shacal-test-loot-window) .item[data-item-type="t-leg"], ' +
            '.loot-wnd:not(.shacal-test-loot-window) .item[data-frame-mania-rarity="legendary"]'
        ).forEach(element => {
            if (
                legendaryChatProcessedLootNodes.has(element) ||
                legendaryChatRetryingLootNodes.has(element)
            ) {
                return;
            }

            tryAnnounceLegendaryLootElement(element);
        });
    }

    function scanLegendaryInventoryAnnouncements() {
        if (
            !settings.chatAnnouncementsEnabled ||
            !legendaryChatTrackerArmed ||
            legendaryChatCandidates.size === 0
        ) {
            return;
        }

        const now = Date.now();

        for (const [id, candidate] of legendaryChatCandidates) {
            if (now - candidate.createdAt > 5 * 60 * 1000) {
                legendaryChatCandidates.delete(id);
            }
        }

        document.querySelectorAll(
            '.inventory-item[data-item-type="t-leg"], ' +
            '.inventory-item[data-frame-mania-rarity="legendary"]'
        ).forEach(element => {
            const itemObject = getItemObjectFromElement(element);
            const id = getItemIdFromElement(element, itemObject);

            if (!id || !legendaryChatCandidates.has(id)) return;
            if (!itemObject?.hid) return;

            enqueueLegendaryGlobalAnnouncement(id, itemObject);
        });
    }

    function scanLegendaryChatTracker() {
        scanLegendaryLootCandidates();
        scanLegendaryInventoryAnnouncements();
    }

    function resetLegendaryChatTracker() {
        legendaryChatTrackerArmed = false;
        legendaryChatProcessedLootNodes = new WeakSet();
        legendaryChatRetryingLootNodes = new WeakSet();
        legendaryChatCandidates.clear();
        legendaryChatQueue.length = 0;
        legendaryChatQueuedIds.clear();
        legendaryChatQueueBusy = false;
    }

    function primeLegendaryChatTracker() {
        resetLegendaryChatTracker();

        /*
         * Celowo ignorujemy wszystko, co już jest widoczne w chwili
         * włączenia funkcji. Dzięki temu aktywacja dodatku nie ogłasza
         * starych legend ani aktualnie otwartego, wcześniejszego łupu.
         * Nowa legenda, która pojawi się później w oknie Łupy, jest wysyłana od razu.
         */
        document.querySelectorAll(
            '.loot-wnd:not(.shacal-test-loot-window) .item[data-item-type="t-leg"], ' +
            '.loot-wnd:not(.shacal-test-loot-window) .item[data-frame-mania-rarity="legendary"]'
        ).forEach(element => {
            legendaryChatProcessedLootNodes.add(element);
        });

        legendaryChatTrackerArmed = true;
    }

    const upgradeBadgeOverlayMap = new Map();

    function getItemUpgradeLevel(element) {
        if (!(element instanceof Element)) return null;

        // Margonem zapisuje faktyczny poziom ulepszenia w data-upgrade.
        // Brak atrybutu = przedmiot nie jest ulepszany.
        // 0 i więcej = pokazujemy dokładną wartość.
        const raw =
            element.getAttribute('data-upgrade');

        if (raw === null || raw === '') {
            return null;
        }

        const level = Number(raw);

        if (!Number.isFinite(level) || level < 0) {
            return null;
        }

        return Math.floor(level);
    }

    function removeUpgradeBadgeOverlay(element) {
        const badge = upgradeBadgeOverlayMap.get(element);

        if (badge) {
            badge.remove();
            upgradeBadgeOverlayMap.delete(element);
        }
    }

    function getItemRarityForUpgradeBadge(element) {
        const maniaRarity =
            element.getAttribute('data-frame-mania-rarity');

        if (
            ['common', 'unique', 'heroic', 'upgraded', 'legendary']
                .includes(maniaRarity)
        ) {
            return maniaRarity;
        }

        const itemType =
            element.getAttribute('data-item-type');

        return {
            't-norm': 'common',
            't-uni': 'unique',
            't-uniupg': 'unique',
            't-her': 'heroic',
            't-upgraded': 'upgraded',
            't-upg': 'upgraded',
            't-leg': 'legendary'
        }[itemType] || 'common';
    }

    function getUpgradeBadgeRarityPalette(element) {
        const rarity =
            getItemRarityForUpgradeBadge(element);

        const base = {
            common: {
                color: '#58656a',
                bright: '#aebdc2',
                dark: '#101619',
                glow: 'rgba(120,145,153,.40)',
                text: '#f2f6f7'
            },
            unique: {
                color: '#927019',
                bright: '#c0922c',
                dark: '#261b04',
                glow: 'rgba(146,112,25,.58)',
                text: '#fff1b0'
            },
            heroic: {
                color: '#1d6f9c',
                bright: '#3395c2',
                dark: '#071f2c',
                glow: 'rgba(29,111,156,.58)',
                text: '#d8f3ff'
            },
            upgraded: {
                color: '#087a32',
                bright: '#10a447',
                dark: '#031c0c',
                glow: 'rgba(8,122,50,.60)',
                text: '#d7ffe3'
            },
            legendary: {
                color: '#e842a2',
                bright: '#ffb5e3',
                dark: '#74164d',
                glow: 'rgba(232,66,162,.66)',
                text: '#ffe4f5'
            }
        };

        const frameSet =
            Number(settings.itemFrameSet) || 1;

        if (rarity === 'legendary') {
            const legendaryPalettes = {
                20: { color:'#d52d2d', bright:'#ff6952', dark:'#5c0c12', glow:'rgba(205,28,38,.62)', text:'#ffe0db' },
                21: { color:'#e85b22', bright:'#ff9442', dark:'#7e1e08', glow:'rgba(238,74,18,.58)', text:'#ffe4c7' },
                22: { color:'#d96b1f', bright:'#ffa84a', dark:'#9d360d', glow:'rgba(220,77,16,.62)', text:'#ffe7c2' },
                23: { color:'#b72b39', bright:'#e04349', dark:'#4d0812', glow:'rgba(154,22,34,.60)', text:'#ffd9de' },
                24: { color:'#e07a25', bright:'#f68230', dark:'#79190b', glow:'rgba(215,60,20,.58)', text:'#ffe2c9' },
                25: { color:'#8cbf35', bright:'#a9d64c', dark:'#365814', glow:'rgba(104,153,35,.56)', text:'#edffd2' },
                26: { color:'#c8652c', bright:'#db6f3b', dark:'#6a2448', glow:'rgba(165,56,50,.54)', text:'#ffe1d5' },
                27: { color:'#861526', bright:'#b92b3b', dark:'#180309', glow:'rgba(145,18,37,.58)', text:'#ffd6dc' }
            };

            if (legendaryPalettes[frameSet]) {
                return legendaryPalettes[frameSet];
            }
        }

        const customFramePalettes = {
            28: {
                unique:    { color:'#655f00', bright:'#8b8500', dark:'#211f00', glow:'rgba(101,98,0,.44)', text:'#fff6a8' },
                heroic:    { color:'#00595d', bright:'#00767c', dark:'#001f22', glow:'rgba(0,89,93,.44)', text:'#c8ffff' },
                upgraded:  { color:'#296500', bright:'#3b8700', dark:'#102300', glow:'rgba(41,101,0,.44)', text:'#d9ffbd' },
                legendary: { color:'#5e001f', bright:'#86002f', dark:'#1c0009', glow:'rgba(94,0,31,.48)', text:'#ffd2df' }
            },
            29: {
                unique:    { color:'#464403', bright:'#656100', dark:'#181700', glow:'rgba(70,68,3,.40)', text:'#fff7aa' },
                heroic:    { color:'#014347', bright:'#00636a', dark:'#00181a', glow:'rgba(1,67,71,.40)', text:'#c9ffff' },
                upgraded:  { color:'#1e4603', bright:'#2d6805', dark:'#0c1a01', glow:'rgba(30,70,3,.40)', text:'#dcffc5' },
                legendary: { color:'#46001c', bright:'#68002a', dark:'#150008', glow:'rgba(70,0,28,.44)', text:'#ffd5e1' }
            }
        };

        return (
            customFramePalettes[frameSet]?.[rarity] ||
            base[rarity] ||
            base.common
        );
    }

    function applyUpgradeBadgeRarityColor(element, badge) {
        const enabled =
            settings.upgradeBadgeSyncRarityColor;

        badge.classList.toggle(
            'shacal-upgrade-rarity-sync',
            enabled
        );

        if (!enabled) {
            [
                '--sg-upgrade-color',
                '--sg-upgrade-bright',
                '--sg-upgrade-dark',
                '--sg-upgrade-glow',
                '--sg-upgrade-text'
            ].forEach(name => badge.style.removeProperty(name));

            return;
        }

        const palette =
            getUpgradeBadgeRarityPalette(element);

        badge.style.setProperty(
            '--sg-upgrade-color',
            palette.color
        );
        badge.style.setProperty(
            '--sg-upgrade-bright',
            palette.bright
        );
        badge.style.setProperty(
            '--sg-upgrade-dark',
            palette.dark
        );
        badge.style.setProperty(
            '--sg-upgrade-glow',
            palette.glow
        );
        badge.style.setProperty(
            '--sg-upgrade-text',
            palette.text
        );
    }

    function ensureUpgradeBadgeOverlay(element) {
        let badge = upgradeBadgeOverlayMap.get(element);

        if (!badge) {
            badge = document.createElement('div');
            badge.className = 'shacal-upgrade-badge';
            badge.setAttribute('aria-hidden', 'true');
            document.body.appendChild(badge);
            upgradeBadgeOverlayMap.set(element, badge);
        }

        return badge;
    }

    function positionUpgradeBadgeOverlay(element, badge) {
        const rect = element.getBoundingClientRect();

        if (
            rect.width <= 0 ||
            rect.height <= 0 ||
            rect.bottom < 0 ||
            rect.right < 0 ||
            rect.top > window.innerHeight ||
            rect.left > window.innerWidth
        ) {
            badge.style.display = 'none';
            return;
        }

        badge.style.display = 'flex';

        const style = Number(settings.upgradeBadgeStyle) || 1;

        const badgeSizes = {
            1: [12, 12],
            2: [12, 12],
            3: [10, 10],
            4: [13, 11],
            5: [11, 11],
            6: [11, 11],
            7: [12, 12],
            8: [11, 11],
            9: [12, 12],
            10: [11, 11],
            11: [11, 11],
            12: [10, 10],
            13: [13, 10],
            14: [12, 12],
            15: [11, 11],
            16: [10, 10]
        };

        const [badgeWidth, badgeHeight] =
            badgeSizes[style] || badgeSizes[1];

        // Nakładka jest przyklejona do prawego górnego rogu samego itemu,
        // ale żyje bezpośrednio w body, więc gra nie może jej schować
        // pod canvasem, highlightem ani ramką slotu.
        badge.style.left =
            `${Math.round(rect.right - badgeWidth + 2)}px`;
        badge.style.top =
            `${Math.round(rect.top - 2)}px`;
    }

    function syncUpgradeBadges() {
        const validElements = new Set();

        if (settings.upgradeBadgeEnabled) {
            document
                .querySelectorAll('.item[data-upgrade]')
                .forEach(element => {
                    const level = getItemUpgradeLevel(element);

                    if (
                        level === null ||
                        element.classList.contains('bag') ||
                        element.closest('.shacal-test-loot-window')
                    ) {
                        removeUpgradeBadgeOverlay(element);
                        return;
                    }

                    validElements.add(element);

                    const badge = ensureUpgradeBadgeOverlay(element);
                    badge.dataset.style =
                        String(settings.upgradeBadgeStyle);
                    badge.textContent =
                        String(level);

                    applyUpgradeBadgeRarityColor(
                        element,
                        badge
                    );

                    positionUpgradeBadgeOverlay(element, badge);
                });
        }

        for (const [element, badge] of upgradeBadgeOverlayMap.entries()) {
            if (
                !settings.upgradeBadgeEnabled ||
                !element.isConnected ||
                !validElements.has(element)
            ) {
                badge.remove();
                upgradeBadgeOverlayMap.delete(element);
            }
        }
    }

    // =========================================================
    // OBSERWATOR
    // =========================================================

    let upgradeBadgeSyncQueued = false;

    function queueUpgradeBadgeSync() {
        if (upgradeBadgeSyncQueued) return;

        upgradeBadgeSyncQueued = true;

        requestAnimationFrame(() => {
            upgradeBadgeSyncQueued = false;
            syncUpgradeBadges();
        });
    }

    const observer = new MutationObserver(mutations => {
        let shouldSyncUpgradeBadges = false;

        for (const mutation of mutations) {
            if (
                mutation.type === 'attributes' &&
                mutation.attributeName === 'data-upgrade'
            ) {
                shouldSyncUpgradeBadges = true;
                break;
            }

            if (mutation.type === 'childList') {
                const changedNodes = [
                    ...mutation.addedNodes,
                    ...mutation.removedNodes
                ];

                if (
                    changedNodes.some(node =>
                        node instanceof Element &&
                        (
                            node.matches?.('.item[data-upgrade]') ||
                            node.querySelector?.('.item[data-upgrade]')
                        )
                    )
                ) {
                    shouldSyncUpgradeBadges = true;
                    break;
                }
            }
        }

        if (shouldSyncUpgradeBadges) {
            queueUpgradeBadgeSync();
        }

        if (settings.chatEmoticonsEnabled) {
            for (const mutation of mutations) {
                if (mutation.type !== 'childList') {
                    continue;
                }

                mutation.addedNodes.forEach(node => {
                    renderChatEmoticonsInRoot(node);
                });
            }
        }

        updateLootWindows();
        scanLegendaryChatTracker();
    });

    observer.observe(document.body, {
        childList: true,
        subtree: true,
        attributes: true,
        attributeFilter: [
            'data-frame-mania-rarity',
            'data-item-type',
            'data-frame-mania-upgrade',
            'data-upgrade'
        ]
    });

    // Pozycję istniejących badge'y odświeżamy lekko tylko przy realnym
    // przesuwaniu/skalowaniu interfejsu, zamiast skanować cały ekwipunek
    // w każdej klatce animacji.
    let upgradeBadgePositionQueued = false;

    function queueUpgradeBadgePositionSync() {
        if (upgradeBadgePositionQueued) return;

        upgradeBadgePositionQueued = true;

        requestAnimationFrame(() => {
            upgradeBadgePositionQueued = false;

            for (const [element, badge] of upgradeBadgeOverlayMap.entries()) {
                if (element.isConnected && badge.isConnected) {
                    positionUpgradeBadgeOverlay(element, badge);
                }
            }
        });
    }

    window.addEventListener('resize', queueUpgradeBadgePositionSync, {
        passive: true
    });

    window.addEventListener('scroll', queueUpgradeBadgePositionSync, {
        passive: true,
        capture: true
    });


    // Lekka pętla tylko do pozycjonowania już istniejących badge'y.
    // Nie skanuje DOM-u i nie tworzy nowych elementów, więc nie powoduje
    // problemu wydajnościowego z v4.1.7, a badge płynnie trzyma się itemu
    // podczas animacji/przesuwania okien i dymków.
    function syncUpgradeBadgePositionsFrame() {
        if (
            settings.upgradeBadgeEnabled &&
            upgradeBadgeOverlayMap.size > 0
        ) {
            for (const [element, badge] of upgradeBadgeOverlayMap.entries()) {
                if (
                    element.isConnected &&
                    badge.isConnected
                ) {
                    positionUpgradeBadgeOverlay(element, badge);
                }
            }
        }

        requestAnimationFrame(syncUpgradeBadgePositionsFrame);
    }

