function prepareLegendaryItem(testWindow) {
        const item = testWindow.querySelector('.item');

        if (!item) return;

        item.setAttribute(
            'data-frame-mania-rarity',
            'legendary'
        );

        item.setAttribute(
            'data-item-type',
            't-leg'
        );

        const highlight =
            item.querySelector('.highlight');

        if (highlight) {
            highlight.classList.remove(
                't-uni',
                't-her',
                't-upg'
            );

            highlight.classList.add('t-leg');
        }
    }

function createLegendaryTestWindow() {
        closeLegendaryTestWindow();

        const holder = document.createElement('div');
        holder.innerHTML = BUILTIN_LOOT_TEMPLATE.trim();

        const test = holder.firstElementChild;
        if (!test) return null;

        test.classList.add(
            'shacal-test-loot-window',
            'shacal-custom-glow'
        );

        /*
         * Test używa docelowego DOM okna Łupy i istniejących styli gry,
         * dlatego wygląda tak samo jak prawdziwe okno lootu.
         */
        test.style.position = 'absolute';
        test.style.display = 'block';
        test.style.zIndex = '999998';

        document.body.appendChild(test);

        const centerTestWindow = () => {
            const rect = test.getBoundingClientRect();

            test.style.left =
                Math.max(
                    0,
                    (window.innerWidth - rect.width) / 2
                ) + 'px';

            test.style.top =
                Math.max(
                    0,
                    (window.innerHeight - rect.height) / 2
                ) + 'px';
        };

        /*
         * Canvas w oryginalnym oknie jest rysowany przez grę.
         * Do testu wystarczy sam slot legendy; poświata wykrywa
         * data-frame-mania-rarity / data-item-type.
         */
        prepareLegendaryItem(test);

        const wantButton =
            test.querySelector('.button.want');

        const notButton =
            test.querySelector('.button.not');

        if (wantButton) {
            wantButton.addEventListener(
                'click',
                event => {
                    event.preventDefault();
                    event.stopPropagation();

                    const wrapper =
                        test.querySelector(
                            '.loot-item-wrapper'
                        );

                    if (wrapper) {
                        wrapper.dataset.state = 'want';
                    }
                }
            );
        }

        if (notButton) {
            notButton.addEventListener(
                'click',
                event => {
                    event.preventDefault();
                    event.stopPropagation();

                    const wrapper =
                        test.querySelector(
                            '.loot-item-wrapper'
                        );

                    if (wrapper) {
                        wrapper.dataset.state = 'not';
                    }
                }
            );
        }

        const closeTest = event => {
            if (event) {
                event.preventDefault();
                event.stopPropagation();
            }

            closeLegendaryTestWindow();
        };

        const acceptButton =
            test.querySelector('.accept-button');

        const closeButton =
            test.querySelector('.close-button');

        if (acceptButton) {
            acceptButton.addEventListener(
                'click',
                closeTest
            );
        }

        if (closeButton) {
            closeButton.addEventListener(
                'click',
                closeTest
            );
        }

        requestAnimationFrame(() => {
            centerTestWindow();
            updateLootWindows();
            syncAllGlowOverlays();

            requestAnimationFrame(() => {
                centerTestWindow();
                syncAllGlowOverlays();
            });
        });

        return test;
    }

    function closeLegendaryTestWindow() {
        document
            .querySelectorAll('.shacal-test-loot-window')
            .forEach(el => el.remove());
    }

